+///|
+fn diagnostic_previous_loss(source : Json) -> Json {
+  let event = diagnostic_recording_event("degraded", "previous_run_unflushed")
+  set_field(event, "missingRange", Json::string("unknown"))
+  if field(source, "affectedRunId") != Some(Json::string("unknown")) &&
+    field(source, "runId") is Some(Json::String(id)) &&
+    id.length() > 0 &&
+    id.length() <= 80 &&
+    id.iter().all(c => (c >= '0' && c <= '9') || c == '_') {
+    set_field(event, "runId", Json::string(id))
+  } else {
+    set_field(event, "affectedRunId", Json::string("unknown"))
+  }
+  for name in ["missingFromTime", "missingThroughTime"] {
+    if field(source, name) is Some(Json::String(value)) &&
+      value.length() > 0 &&
+      value.length() <= 25 &&
+      value.iter().all(c => c >= '0' && c <= '9') {
+      set_field(event, name, Json::string(value))
+    }
+  }
+  if field(event, "missingFromTime") is Some(_) &&
+    field(event, "missingThroughTime") is Some(_) {
+    set_field(event, "missingRange", Json::string("observed"))
+  }
+  let reason = field(source, "previousReason").unwrap_or(
+    field(source, "reason").unwrap_or(Json::null()),
+  )
+  if reason is Json::String(value) &&
+    [
+      "lock_busy", "invalid_lock", "invalid_store", "store_timeout", "store_unavailable",
+      "buffer_full", "protected_values_unavailable", "workspace_recording_unknown",
+    ].contains(value) {
+    set_field(event, "previousReason", reason)
+  }
+  event
+}
+
+///|
+async fn recover_diagnostic_health(directory : String) -> Unit {
+  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
+    return
+  }
+  let path = directory + "/diagnostic-health.json"
+  if !@fs.exists(path) {
+    return
+  }
+  let previous = @async.with_timeout(20, async fn() {
+    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
+      @fs.file_size(path) <= 65536L else {
+      return Json::null()
+    }
+    @json.parse(@fs.read_file(path).text())
+  }) catch {
+    error =>
+      if @async.is_being_cancelled() {
+        raise error
+      } else {
+        Json::null()
+      }
+  }
+  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
+    for loss in losses {
+      if diagnostic_previous_losses.length() >= 31 {
+        break
+      }
+      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
+    }
+    if losses.length() > 31 {
+      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
+    }
+  }
+  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
+  for event in diagnostic_previous_losses {
+    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
+  }
+  diagnostic_recording_health.incident = true
+  diagnostic_recording_health.reason = "previous_run_unflushed"
+  diagnostic_recording_health.phase = "recovery"
+}
+
+///|
+priv struct DiagnosticStructuredSecrets {
+  values : Array[String]
+  mut visited : Int32
+  mut incomplete : Bool
+}
+
+///|
+fn diagnostic_structured_secrets(
+  value : Json,
+  found : DiagnosticStructuredSecrets,
+  secret~ : Bool = false,
+  depth~ : Int32 = 0,
+) -> Unit {
+  if found.visited >= 65536 || depth >= 64 {
+    found.incomplete = true
+    return
+  }
+  found.visited += 1
+  match value {
+    Json::String(text) if secret && text != "" && text != "[redacted]" => {
+      add_protected_secret(found.values, text)
+      if found.values.length() > 512 {
+        found.incomplete = true
+      }
+    }
+    Json::Number(_, ..) if secret => {
+      add_protected_secret(found.values, value.stringify())
+      if found.values.length() > 512 {
+        found.incomplete = true
+      }
+    }
+    Json::Array(values) =>
+      for item in values {
+        if found.incomplete {
+          break
+        }
+        diagnostic_structured_secrets(item, found, secret~, depth=depth + 1)
+      }
+    Json::Object(values) =>
+      for name, item in values {
+        if found.incomplete {
+          break
+        }
+        let key = name.to_lower().replace_all(old="_", new="")
+        diagnostic_structured_secrets(
+          item,
+          found,
+          secret=secret ||
+            credential_field(name, for_diagnostics=true) ||
+            key == "pairingcode",
+          depth=depth + 1,
+        )
+      }
+    _ => ()
+  }
+}
+
+///|
+fn diagnostic_json(
+  value : Json,
+  environment : Map[String, String],
+  protected_secrets : Array[String],
+  truncated : Ref[Bool],
+  depth : Int32,
+  stable_activity~ : Bool = false,
+  secret_states~ : Bool = false,
+  stable_operation~ : Bool = false,
+  stable_arguments~ : Bool = false,
+  parent~ : String = "",
+) -> Json {
+  let protected_secrets = if depth == 0 {
+    let found : DiagnosticStructuredSecrets = {
+      values: [],
+      visited: 0,
+      incomplete: false,
+    }
+    diagnostic_structured_secrets(value, found)
+    if found.incomplete {
+      truncated.val = true
+      return { "reason": "protected_value_limit", "detailsTruncated": true }
+    }
+    protected_secrets + found.values
+  } else {
+    protected_secrets
+  }
+  if depth >= 64 {
+    truncated.val = true
+    return Json::string("[nested evidence omitted]")
+  }
+  match value {
+    Json::Object(values) => {
+      let result = Json::empty_object()
+      for name, item in values {
+        let key = name.to_lower().replace_all(old="_", new="")
+        let safe_name = if (
+            stable_arguments &&
+            [
+              "arguments", "value", "source", "argumentCount", "reason", "command",
+              "home", "context", "state", "effectiveContext",
+            ].contains(name)
+          ) ||
+          (
+            stable_operation &&
+            (
+              (
+                depth == 0 &&
+                [
+                  "operationId", "workspaceId", "invocation", "backend", "phaseObservation",
+                ].contains(name)
+              ) ||
+              (
+                depth == 1 &&
+                [
+                  "command", "resolvedProgram", "lookupPath", "workingDirectory",
+                  "sshAuthSock",
+                ].contains(name)
+              ) ||
+              (
+                parent == "backend" &&
+                [
+                  "kind", "phase", "state", "pipeline", "operationId", "step", "durationMs",
+                  "error",
+                ].contains(name)
+              ) ||
+              (parent == "phaseObservation" && name == "reason")
+            )
+          ) ||
+          (
+            stable_activity &&
+            [
+              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
+              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
+              "workspaceId", "source", "code", "id", "uid", "context", "provider",
+              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
+              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
+              "error", "autoStop", "orcaVersion", "handle", "connected", "foregroundProcess",
+              "hasChildProcesses", "processEvidence", "verdict", "capturedAgeMs",
+              "ptyIncarnationId", "observationEpoch", "stateStartedAt", "updatedAt",
+              "working", "queuedMessages", "actionablePrompts", "backgroundTasks",
+            ].contains(name)
+          ) {
+          name
+        } else {
+          diagnostic_text(name, environment~, protected_secrets~)
+        }
+        if field(result, safe_name) is Some(_) {
+          truncated.val = true
+          continue
+        }
+        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
+          truncated.val = true
+        }
+        set_field(
+          result,
+          safe_name,
+          if credential_field(name, for_diagnostics=true) ||
+            key == "pairingcode" {
+            if secret_states &&
+              field(item, "state") is Some(Json::String(state)) &&
+              ["unset", "empty", "set"].contains(state) {
+              let masked : Json = { "state": state }
+              if field(item, "value") is Some(_) {
+                set_field(masked, "value", Json::string("[redacted]"))
+              }
+              if field(item, "truncated") == Some(Json::boolean(true)) {
+                set_field(masked, "truncated", Json::boolean(true))
+                truncated.val = true
+              }
+              masked
+            } else {
+              Json::string("[redacted]")
+            }
+          } else if stable_activity &&
+            name == "activity" &&
+            (
+              item == Json::string("idle") ||
+              item == Json::string("active") ||
+              item == Json::string("unknown")
+            ) {
+            item
+          } else if stable_activity &&
+            parent == "agent" &&
+            item is Json::String(text) &&
+            (
+              (
+                name == "state" &&
+                ["working", "waiting", "blocked", "monitoring", "done"].contains(
+                  text,
+                )
+              ) ||
+              (
+                name == "programState" &&
+                ["working", "blocked", "idle"].contains(text)
+              )
+            ) {
+            item
+          } else {
+            diagnostic_json(
+              item,
+              environment,
+              protected_secrets,
+              truncated,
+              depth + 1,
+              stable_activity~,
+              secret_states~,
+              stable_operation~,
+              stable_arguments~,
+              parent=name,
+            )
+          },
+        )
+      }
+      result
+    }
+    Json::Array(values) =>
+      Json::array(
+        values.map(item => {
+          diagnostic_json(
+            item,
+            environment,
+            protected_secrets,
+            truncated,
+            depth + 1,
+            stable_activity~,
+            secret_states~,
+            stable_operation~,
+            stable_arguments~,
+            parent~,
+          )
+        }),
+      )
+    Json::String(text) => {
+      let safe = diagnostic_text(text, environment~, protected_secrets~)
+      if safe.has_suffix("\n[error details incomplete or truncated]") {
+        truncated.val = true
+      }
+      Json::string(safe)
+    }
+    Json::Number(_, ..) if protected_secrets.contains(value.stringify()) =>
+      Json::string("[redacted]")
+    _ => value
+  }
+}
