+///|
+priv struct PrivateKeyMatcher {
+  mut active : Bool
+  mut candidate : Bool
+  tail : Array[Char]
+}
+
+///|
+priv struct PrivateKeyScanner {
+  raw : PrivateKeyMatcher
+  terminal : PrivateKeyMatcher
+  mut terminal_state : Int32
+  escape : Array[Char]
+}
+
+///|
+let private_key_begin_prefix : Array[Char] = "-----begin ".iter().to_array()
+
+///|
+let private_key_end_prefix : Array[Char] = "-----end ".iter().to_array()
+
+///|
+let private_key_end_marker : Array[Char] = "private key-----".iter().to_array()
+
+///|
+let private_key_dashes : Array[Char] = "-----".iter().to_array()
+
+///|
+fn PrivateKeyScanner::new(active : Bool) -> PrivateKeyScanner {
+  {
+    raw: { active, candidate: false, tail: [], },
+    terminal: { active, candidate: false, tail: [], },
+    terminal_state: 0,
+    escape: [],
+  }
+}
+
+///|
+fn PrivateKeyMatcher::plain(self : PrivateKeyMatcher, c : Char) -> Unit {
+  let c = if c >= 'A' && c <= 'Z' {
+    (c.to_int() + 32).unsafe_to_char()
+  } else {
+    c
+  }
+  self.tail.push(c)
+  if self.tail.length() > 32 {
+    ignore(self.tail.remove(0))
+  }
+  let suffix = fn(pattern : Array[Char]) {
+    self.tail.length() >= pattern.length() &&
+    ascii_match_at(self.tail, self.tail.length() - pattern.length(), pattern)
+  }
+  if !self.candidate {
+    self.candidate = suffix(
+      if self.active {
+        private_key_end_prefix
+      } else {
+        private_key_begin_prefix
+      },
+    )
+  } else if suffix(private_key_end_marker) {
+    self.active = !self.active
+    self.candidate = false
+    self.tail.clear()
+  } else if suffix(private_key_dashes) {
+    self.candidate = false
+  }
+}
+
+///|
+fn PrivateKeyMatcher::reset(self : PrivateKeyMatcher, active : Bool) -> Unit {
+  self.active = active
+  self.candidate = false
+  self.tail.clear()
+}
+
+///|
+fn PrivateKeyScanner::plain(self : PrivateKeyScanner, c : Char) -> Unit {
+  let raw_before = self.raw.active
+  self.raw.plain(c)
+  if self.raw.active != raw_before {
+    self.terminal.reset(self.raw.active)
+  }
+  let mut emit = false
+  match self.terminal_state {
+    0 => if c == '\u001b' { self.terminal_state = 1 } else { emit = true }
+    1 =>
+      if c == '[' {
+        self.terminal_state = 2
+      } else if c == ']' {
+        self.terminal_state = 3
+      } else {
+        self.terminal_state = 0
+        emit = true
+      }
+    2 => if c >= '@' && c <= '~' { self.terminal_state = 0 }
+    3 =>
+      if c == '\u0007' {
+        self.terminal_state = 0
+      } else if c == '\u001b' {
+        self.terminal_state = 4
+      }
+    _ =>
+      if c == '\\' {
+        self.terminal_state = 0
+      } else if c != '\u001b' {
+        self.terminal_state = 3
+      }
+  }
+  if emit {
+    let terminal_before = self.terminal.active
+    self.terminal.plain(c)
+    if self.terminal.active != terminal_before {
+      self.raw.reset(self.terminal.active)
+    }
+  }
+}
+
+///|
+fn PrivateKeyScanner::flush_escape(self : PrivateKeyScanner) -> Unit {
+  for c in self.escape {
+    self.plain(c)
+  }
+  self.escape.clear()
+}
+
+///|
+fn PrivateKeyScanner::feed(self : PrivateKeyScanner, text : String) -> Unit {
+  for c in text.iter() {
+    if self.escape.is_empty() {
+      if c == '\\' {
+        self.escape.push(c)
+      } else {
+        self.plain(c)
+      }
+    } else if self.escape.length() == 1 && c == 'u' {
+      self.escape.push(c)
+    } else if self.escape.length() >= 2 && credential_hex(c) is Some(_) {
+      self.escape.push(c)
+      if self.escape.length() == 6 {
+        let code = credential_hex(self.escape[2]).unwrap() * 4096 +
+          credential_hex(self.escape[3]).unwrap() * 256 +
+          credential_hex(self.escape[4]).unwrap() * 16 +
+          credential_hex(self.escape[5]).unwrap()
+        if (code >= 32 && code <= 126) || code == 27 || code == 7 {
+          self.escape.clear()
+          self.plain(code.unsafe_to_char())
+        } else {
+          self.flush_escape()
+        }
+      }
+    } else {
+      self.flush_escape()
+      if c == '\\' {
+        self.escape.push(c)
+      } else {
+        self.plain(c)
+      }
     }
+  }
+}
+
+///|
+fn PrivateKeyScanner::finish(self : PrivateKeyScanner) -> Bool {
+  self.flush_escape()
+  if !self.raw.active && (self.raw.candidate || self.terminal.candidate) {
+    return true
+  }
+  self.raw.active || self.terminal.active
+}
+
+///|
+fn decode_diagnostic_escapes(text : String) -> String {
+  let chars = text.iter().to_array()
+  let output = @buffer.Buffer(size_hint=text.length())
+  let mut i = 0
+  while i < chars.length() {
+    if chars[i] == '\\' &&
+      i + 5 < chars.length() &&
+      chars[i + 1] == 'u' &&
+      credential_hex(chars[i + 2]) is Some(a) &&
+      credential_hex(chars[i + 3]) is Some(b) &&
+      credential_hex(chars[i + 4]) is Some(c) &&
+      credential_hex(chars[i + 5]) is Some(d) {
+      let value = a * 4096 + b * 256 + c * 16 + d
+      if value >= 32 && value <= 126 {
+        output.write_char_utf8(value.unsafe_to_char())
+        i += 6
+        continue
+      }
+    }
+    output.write_char_utf8(chars[i])
+    i += 1
+  }
+  @utf8.decode_lossy(output.to_bytes())
+}
