+///|
+fn Progress::filter_output_line(
+  self : Progress,
+  line : String,
+  private_key : Ref[Bool],
+) -> String? {
+  let event = @json.parse(line) catch { _ => Json::null() }
+  self.learn_event(event, line)
+  let normalized = if event != Json::null() {
+    let truncated : Ref[Bool] = { val: false, }
+    let value = progress_normalize_json(event, truncated, 0)
+    if truncated.val {
+      self.details_truncated = true
+      let scanner = PrivateKeyScanner::new(private_key.val)
+      scanner.feed(line)
+      private_key.val = scanner.finish()
+      return None
+    }
+    value.stringify()
+  } else {
+    match terminal_text(line) {
+      Some(text) => decode_diagnostic_escapes(text)
+      None => {
+        self.details_truncated = true
+        let scanner = PrivateKeyScanner::new(private_key.val)
+        scanner.feed(line)
+        private_key.val = scanner.finish()
+        return None
+      }
+    }
+  }
+  let scanner = PrivateKeyScanner::new(private_key.val)
+  scanner.feed(normalized)
+  let scanned_private = scanner.finish()
+  let truncated : Ref[Bool] = { val: false, }
+  let safe = mask_private_key(normalized, private_key, truncated)
+  if truncated.val {
+    self.details_truncated = true
+  }
+  if scanned_private && !private_key.val {
+    self.details_truncated = true
+    private_key.val = true
+    guard safe is Some(safe) else { return None }
+    let chars = safe.iter().to_array()
+    let prefix = "-----begin ".iter().to_array()
+    for index in 0..<chars.length() {
+      if ascii_match_at(chars, index, prefix) {
+        return Some(character_text(chars, 0, index) + "[private key redacted]")
+      }
+    }
+    return None
+  }
+  safe
+}
