+      field(event, "state") == Some(Json::string("failed")) {
+      self.message(safe, debug=false, warning=true, emit=false)
+    } else {
+      self.remember_unrecognized(safe)
+    }
+    return
+  } else if event == Json::null() &&
+    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
+    self.details_truncated = true
+    self.message(line, debug=false, warning=true, emit=false)
+    return
+  }
+  self.line(line, statuses~, messages~)
