///|
fn credential_field(name : String, for_diagnostics~ : Bool = false) -> Bool {
  let exact_names = [
    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
    "x_amz_security_token", "x_goog_signature",
  ]
  if !for_diagnostics {
    let original = name
      .trim_start(chars="-")
      .to_owned()
      .to_lower()
      .replace_all(old="-", new="_")
    return exact_names.contains(original) ||
      [
        "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
      ]
      .iter()
      .any(suffix => original.has_suffix(suffix))
  }
  let chars = name.trim_start(chars="-").iter().to_array()
  let normalized = @buffer.Buffer(size_hint=name.length())
  for i in 0..<chars.length() {
    let c = chars[i]
    if i > 0 &&
      c >= 'A' &&
      c <= 'Z' &&
      (
        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
      ) {
      normalized.write_char_utf8('_')
    }
    normalized.write_char_utf8(if c == '-' { '_' } else { c })
  }
  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
  if name == "ssh_auth_sock" {
