///|
fn PrivateKeyScanner::finish(self : PrivateKeyScanner) -> Bool {
  self.flush_escape()
  if !self.raw.active && (self.raw.candidate || self.terminal.candidate) {
    return true
  }
  self.raw.active || self.terminal.active
}

///|
fn decode_diagnostic_escapes(text : String) -> String {
  let chars = text.iter().to_array()
  let output = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    if chars[i] == '\\' &&
      i + 5 < chars.length() &&
      chars[i + 1] == 'u' &&
      credential_hex(chars[i + 2]) is Some(a) &&
      credential_hex(chars[i + 3]) is Some(b) &&
      credential_hex(chars[i + 4]) is Some(c) &&
      credential_hex(chars[i + 5]) is Some(d) {
      let value = a * 4096 + b * 256 + c * 16 + d
      if value >= 32 && value <= 126 {
        output.write_char_utf8(value.unsafe_to_char())
        i += 6
        continue
      }
    }
    output.write_char_utf8(chars[i])
    i += 1
  }
  @utf8.decode_lossy(output.to_bytes())
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  if self.protection_incomplete {
    self.details_truncated = true
    return None
  }
  guard terminal_text(text) is Some(text) else { return None }
  let state : Ref[Bool] = { val: self.private_key, }
  let truncated : Ref[Bool] = { val: false, }
  let masked = mask_private_key(text, state, truncated)
  self.private_key = REDACTED
  if truncated.val {
    self.details_truncated = true
  }
  guard masked is Some(masked) else { return None }
  let known = redact_known_values(masked, self.secrets)
  let incomplete : Ref[Bool] = { val: false, }
  let mut safe = redact_known_values(
    redact_credentials(known, incomplete~),
    self.secrets,
  )
  if incomplete.val {
    self.details_truncated = true
  }
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}

///|
fn redact_known_values(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let values : Array[Array[Char]] = []
  for secret in secrets {
    if secret.length() <= text.length() {
      values.push(secret.iter().to_array())
    }
  }
  let result = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    let mut matched = 0
    for index in 0..<values.length() {
      let value = values[index]
      let mut matches = value.length() > 0
      let mut cursor = i
      for j in 0..<value.length() {
        if cursor >= chars.length() {
          matches = false
          break
        }
        if chars[cursor] == value[j] ||
          (chars[cursor] == '+' && value[j] == ' ') {
          cursor += 1
          continue
        }
        if chars[cursor] != '%' {
          matches = false
          break
        }
        let encoded = @utf8.encode(value[j].to_string())
        for byte in encoded {
          if cursor + 2 >= chars.length() || chars[cursor] != '%' {
            matches = false
            break
          }
          guard (
              credential_hex(chars[cursor + 1]),
              credential_hex(chars[cursor + 2]),
            )
            is (Some(hi), Some(lo)) &&
            hi * 16 + lo == byte.to_int() else {
            matches = false
            break
          }
          cursor += 3
        }
        if !matches {
          break
        }
      }
      if matches &&
        (
          cursor - i > 10 ||
          i + 10 > chars.length() ||
          character_text(chars, i, i + 10) != "[redacted]"
        ) {
        matched = cursor - i
        break
      }
    }
    if matched > 0 {
      result.write_string_utf8("[redacted]")
      i += matched
    } else if i + 10 <= chars.length() &&
      character_text(chars, i, i + 10) == "[redacted]" {
      result.write_string_utf8("[redacted]")
      i += 10
    } else {
      result.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

