  1	///|
  2	priv struct DiagnosticRecordingHealth {
  3	  mut dropped : Int32
  4	  mut first_dropped : UInt64
  5	  mut last_dropped : UInt64
  6	  mut reason : String
  7	  mut phase : String
  8	  mut os_errno : Int32?
  9	  mut warned : Bool
 10	  mut incident : Bool
 11	  mut incident_serial : UInt64
 12	  mut run_partial : Bool
 13	}
 14	
 15	///|
 16	let diagnostic_recording_health : DiagnosticRecordingHealth = {
 17	  dropped: 0,
 18	  first_dropped: 0,
 19	  last_dropped: 0,
 20	  reason: "",
 21	  phase: "",
 22	  os_errno: None,
 23	  warned: false,
 24	  incident: false,
 25	  incident_serial: 0,
 26	  run_partial: false,
 27	}
 28	
 29	///|
 30	let diagnostic_run_has_events : Ref[Bool] = { val: false, }
 31	
 32	///|
 33	let diagnostic_run_written_count : Ref[Int32] = { val: 0, }
 34	
 35	///|
 36	let diagnostic_previous_losses : Array[Json] = []
 37	
 38	///|
 39	let diagnostic_workspace_environments : Map[String, Map[String, String]] = Map([])
 40	
 41	///|
 42	fn diagnostic_health_snapshot() -> Json {
 43	  if diagnostic_recording_health.incident ||
 44	    diagnostic_recording_health.dropped > 0 {
 45	    {
 46	      "status": "degraded",
 47	      "reason": diagnostic_recording_health.reason,
 48	      "phase": diagnostic_recording_health.phase,
 49	    }
 50	  } else {
 51	    { "status": "healthy" }
 52	  }
 53	}
 54	
 55	///|
 56	async fn publish_diagnostic_health() -> Unit {
 57	  guard @env.args() is [_, "--supervisor", ..] else { return }
 58	  @async.with_timeout(10, async fn() {
 59	    let directory = adapter_state_home()
 60	    let path = directory + "/diagnostic-health.json"
 61	    if !diagnostic_recording_health.incident &&
 62	      diagnostic_recording_health.dropped == 0 {
 63	      @fs.remove(path) catch {
 64	        _ => ()
 65	      }
 66	      return
 67	    }
 68	    let temporary = directory +
 69	      "/diagnostic-health." +
 70	      proxy_pid().to_string() +
 71	      ".tmp"
 72	    defer (@fs.remove(temporary) catch { _ => () })
 73	    let snapshot = diagnostic_health_snapshot()
 74	    set_field(snapshot, "runId", Json::string(recording_run_id))
 75	    set_field(
 76	      snapshot,
 77	      "pendingEvents",
 78	      Json::number(diagnostic_pending.length().to_double()),
 79	    )
 80	    set_field(
 81	      snapshot,
 82	      "droppedEvents",
 83	      Json::number(diagnostic_recording_health.dropped.to_double()),
 84	    )
 85	    let mut first = if diagnostic_recording_health.dropped > 0 {
 86	      Some(diagnostic_recording_health.first_dropped)
 87	    } else {
 88	      None
 89	    }
 90	    let mut last = if diagnostic_recording_health.dropped > 0 {
 91	      Some(diagnostic_recording_health.last_dropped)
 92	    } else {
 93	      None
 94	    }
 95	    for pending in diagnostic_pending {
 96	      if first is None || pending.time < first.unwrap() {
 97	        first = Some(pending.time)
 98	      }
 99	      if last is None || pending.time > last.unwrap() {
100	        last = Some(pending.time)
101	      }
102	    }
103	    if first is Some(time) {
104	      set_field(snapshot, "missingFromTime", Json::string(time.to_string()))
105	    }
106	    if last is Some(time) {
107	      set_field(snapshot, "missingThroughTime", Json::string(time.to_string()))
108	    }
109	    if !diagnostic_previous_losses.is_empty() {
110	      set_field(snapshot, "priorLoss", Json::array(diagnostic_previous_losses))
111	    }
112	    @fs.write_file(temporary, snapshot.stringify(), permission=0o600)
113	    @fs.rename(temporary, path, replace=true)
114	  }) catch {
115	    _ => ()
116	  }
117	}
118	
119	///|
120	async fn diagnostic_recording_warning(
121	  reason : String,
122	  phase~ : String = "",
123	  os_errno? : Int32,
124	) -> Unit {
125	  if reason == "workspace_recording_unknown" {
126	    diagnostic_recording_health.run_partial = true
127	  }
128	  let publish = !diagnostic_recording_health.incident ||
129	    diagnostic_recording_health.reason != reason ||
130	    diagnostic_recording_health.phase != phase
131	  diagnostic_recording_health.incident = true
132	  diagnostic_recording_health.incident_serial += 1
133	  if diagnostic_recording_health.dropped == 0 {
134	    diagnostic_recording_health.reason = reason
135	    diagnostic_recording_health.phase = phase
136	    diagnostic_recording_health.os_errno = os_errno
137	  }
138	  if publish {
139	    publish_diagnostic_health()
140	  }
141	  if !diagnostic_recording_health.warned {
142	    diagnostic_recording_health.warned = true
143	    @async.with_timeout(10, async fn() {
144	      @stdio.stderr.write(
145	        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
146	        reason +
147	        (if phase == "" { "" } else { ", phase=" + phase }) +
148	        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
149	        ")\n",
150	      )
151	    }) catch {
152	      _ => ()
153	    }
154	  }
155	}
156	
157	///|
158	async fn diagnostic_recording_failed(
159	  reason : String,
160	  phase~ : String = "",
161	  os_errno? : Int32,
162	  event_time? : UInt64,
163	) -> Unit {
164	  let time = event_time.unwrap_or(@env.now())
165	  let health_changed = diagnostic_recording_health.reason != reason ||
166	    diagnostic_recording_health.phase != phase
167	  if diagnostic_recording_health.dropped == 0 {
168	    diagnostic_recording_health.first_dropped = time
169	    diagnostic_recording_health.last_dropped = time
170	  } else {
171	    if time < diagnostic_recording_health.first_dropped {
172	      diagnostic_recording_health.first_dropped = time
173	    }
174	    if time > diagnostic_recording_health.last_dropped {
175	      diagnostic_recording_health.last_dropped = time
176	    }
177	  }
178	  diagnostic_recording_health.dropped += 1
179	  diagnostic_recording_health.run_partial = true
180	  diagnostic_recording_health.reason = reason
181	  diagnostic_recording_health.phase = phase
182	  diagnostic_recording_health.os_errno = os_errno
183	  diagnostic_recording_warning(reason, phase~, os_errno?)
184	  if health_changed {
185	    publish_diagnostic_health()
186	  }
187	}
