208	///|
209	fn diagnostic_recording_event(status : String, reason : String) -> Json {
210	  {
211	    "stage": "diagnostic-recording",
212	    "status": status,
213	    "errorType": reason,
214	    "completeness": "partial",
215	    "time": @env.now().to_string(),
216	    "runId": recording_run_id,
217	    "adapterVersion": version,
218	  }
219	}
