221	///|
222	fn diagnostic_previous_loss(source : Json) -> Json {
223	  let event = diagnostic_recording_event("degraded", "previous_run_unflushed")
224	  set_field(event, "missingRange", Json::string("unknown"))
225	  if field(source, "affectedRunId") != Some(Json::string("unknown")) &&
226	    field(source, "runId") is Some(Json::String(id)) &&
227	    id.length() > 0 &&
228	    id.length() <= 80 &&
229	    id.iter().all(c => (c >= '0' && c <= '9') || c == '_') {
230	    set_field(event, "runId", Json::string(id))
231	  } else {
232	    set_field(event, "affectedRunId", Json::string("unknown"))
233	  }
234	  for name in ["missingFromTime", "missingThroughTime"] {
235	    if field(source, name) is Some(Json::String(value)) &&
236	      value.length() > 0 &&
237	      value.length() <= 25 &&
238	      value.iter().all(c => c >= '0' && c <= '9') {
239	      set_field(event, name, Json::string(value))
240	    }
241	  }
242	  if field(event, "missingFromTime") is Some(_) &&
243	    field(event, "missingThroughTime") is Some(_) {
244	    set_field(event, "missingRange", Json::string("observed"))
245	  }
246	  let reason = field(source, "previousReason").unwrap_or(
247	    field(source, "reason").unwrap_or(Json::null()),
248	  )
249	  if reason is Json::String(value) &&
250	    [
251	      "lock_busy", "invalid_lock", "invalid_store", "store_timeout", "store_unavailable",
252	      "buffer_full", "protected_values_unavailable", "workspace_recording_unknown",
253	    ].contains(value) {
254	    set_field(event, "previousReason", reason)
255	  }
256	  event
257	}
