259	///|
260	async fn recover_diagnostic_health(directory : String) -> Unit {
261	  if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
262	    return
263	  }
264	  let path = directory + "/diagnostic-health.json"
265	  if !@fs.exists(path) {
266	    return
267	  }
268	  let previous = @async.with_timeout(20, async fn() {
269	    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
270	      @fs.file_size(path) <= 65536L else {
271	      return Json::null()
272	    }
273	    @json.parse(@fs.read_file(path).text())
274	  }) catch {
275	    error =>
276	      if @async.is_being_cancelled() {
277	        raise error
