315	) -> Unit {
316	  if found.visited >= 65536 || depth >= 64 {
317	    found.incomplete = true
318	    return
319	  }
320	  found.visited += 1
321	  match value {
322	    Json::String(text) if secret && text != "" && text != "[redacted]" => {
323	      add_protected_secret(found.values, text)
324	      if found.values.length() > 512 {
325	        found.incomplete = true
326	      }
327	    }
328	    Json::Number(_, ..) if secret => {
329	      add_protected_secret(found.values, value.stringify())
330	      if found.values.length() > 512 {
331	        found.incomplete = true
332	      }
333	    }
334	    Json::Array(values) =>
335	      for item in values {
336	        if found.incomplete {
337	          break
338	        }
339	        diagnostic_structured_secrets(item, found, secret~, depth=depth + 1)
340	      }
341	    Json::Object(values) =>
342	      for name, item in values {
343	        if found.incomplete {
344	          break
345	        }
346	        let key = name.to_lower().replace_all(old="_", new="")
347	        diagnostic_structured_secrets(
348	          item,
349	          found,
350	          secret=secret ||
351	            credential_field(name, for_diagnostics=true) ||
352	            key == "pairingcode",
353	          depth=depth + 1,
354	        )
355	      }
356	    _ => ()
357	  }
