422	                [
423	                  "kind", "phase", "state", "pipeline", "operationId", "step", "durationMs",
424	                  "error",
425	                ].contains(name)
426	              ) ||
427	              (parent == "phaseObservation" && name == "reason")
428	            )
429	          ) ||
430	          (
431	            stable_activity &&
432	            [
433	              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
434	              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
435	              "workspaceId", "source", "code", "id", "uid", "context", "provider",
436	              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
437	              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
438	              "error", "autoStop", "orcaVersion", "handle", "connected", "foregroundProcess",
439	              "hasChildProcesses", "processEvidence", "verdict", "capturedAgeMs",
440	              "ptyIncarnationId", "observationEpoch", "stateStartedAt", "updatedAt",
441	              "working", "queuedMessages", "actionablePrompts", "backgroundTasks",
442	            ].contains(name)
443	          ) {
444	          name
445	        } else {
