1250	///|
1251	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1252	  let chars = text.iter().to_array()
1253	  let mut boundary = chars.length()
1254	  for secret in secrets {
1255	    let value = secret.iter().to_array()
1256	    if value.length() == 0 || text.has_suffix(secret) {
1257	      continue
1258	    }
1259	    let limit = if value.length() - 1 < boundary {
1260	      value.length() - 1
1261	    } else {
1262	      boundary
1263	    }
1264	    if limit == 0 {
1265	      continue
1266	    }
1267	    let prefixes = FixedArray::make(limit, 0)
1268	    let mut matched = 0
1269	    for index in 1..<limit {
1270	      while matched > 0 && value[matched] != value[index] {
1271	        matched = prefixes[matched - 1]
1272	      }
1273	      if value[matched] == value[index] {
1274	        matched += 1
1275	      }
1276	      prefixes[index] = matched
1277	    }
1278	    matched = 0
1279	    for index in 0..<boundary {
1280	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1281	        matched = prefixes[matched - 1]
1282	      }
1283	      if matched < limit && value[matched] == chars[index] {
1284	        matched += 1
1285	      }
1286	    }
1287	    boundary -= matched
1288	  }
1289	  if boundary == chars.length() {
1290	    text
1291	  } else {
1292	    character_text(chars, 0, boundary) + "[redacted]"
1293	  }
1294	}
