1331	  secret~ : Bool = false,
1332	  depth~ : Int32 = 0,
1333	) -> Unit {
1334	  if result.visited >= 65536 || depth >= 64 {
1335	    result.incomplete = true
1336	    return
1337	  }
1338	  result.visited += 1
1339	  match value {
1340	    Json::Number(_, ..) if secret =>
1341	      diagnostic_add_protected(
1342	        value.stringify(),
1343	        output,
1344	        uncertain,
1345	        result.secrets,
1346	        result,
1347	      )
1348	    Json::String(text) if text != "" && secret => {
1349	      let destination = result.secrets
1350	      diagnostic_add_protected(text, output, uncertain, destination, result)
1351	      for line in text.replace_all(old="\r", new="\n").split("\n") {
1352	        if line != "" && line.length() < text.length() {
1353	          diagnostic_add_protected(
1354	            line.to_owned(),
1355	            output,
1356	            uncertain,
1357	            destination,
1358	            result,
1359	          )
1360	        }
1361	        for word in line.split(" ") {
1362	          for part in word.split("=") {
1363	            if part != "" && part.length() < text.length() {
1364	              diagnostic_add_protected(
1365	                part.to_owned(),
1366	                output,
1367	                uncertain,
1368	                destination,
1369	                result,
1370	              )
1371	            }
1372	          }
1373	        }
1374	      }
1375	      let escaped = Json::string(text).stringify()
1376	      if escaped.length() > 2 {
1377	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1378	        if encoded != text {
1379	          diagnostic_add_protected(
1380	            encoded, output, uncertain, destination, result,
1381	          )
1382	        }
1383	      }
1384	    }
1385	    Json::String(text) if text != "" => {
1386	      let mut next_secret = false
1387	      for word in text.split(" ") {
1388	        let word = word.to_owned()
1389	        if next_secret {
1390	          diagnostic_add_protected(
1391	            word,
1392	            output,
1393	            uncertain,
1394	            result.secrets,
1395	            result,
1396	          )
1397	          next_secret = false
1398	        } else if word.split_once("=") is Some((name, value)) {
1399	          if credential_field(name.to_owned(), for_diagnostics=true) {
1400	            diagnostic_add_protected(
1401	              value.to_owned(),
1402	              output,
1403	              uncertain,
1404	              result.secrets,
1405	              result,
1406	            )
1407	          }
1408	        } else if word.has_prefix("-") &&
1409	          credential_field(word, for_diagnostics=true) {
1410	          next_secret = true
