1199	fn diagnostic_text(
1200	  message : String,
1201	  environment? : Map[String, String],
1202	  omitted~ : Bool = false,
1203	  protected_secrets? : Array[String],
1204	  incomplete_final_line~ : Bool = false,
1205	) -> String {
1206	  let progress = Progress::new("diagnostic-error", environment?)
1207	  if protected_secrets is Some(values) {
1208	    for value in values {
1209	      add_protected_secret(progress.secrets, value)
1210	    }
1211	  }
1212	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
1213	  let lines = []
1214	  let mut incomplete = omitted
1215	  let source_lines = message.split("\n").to_array()
1216	  for index in 0..<source_lines.length() {
1217	    let line = source_lines[index]
1218	    if lines.length() == 32 {
1219	      incomplete = true
1220	      ignore(lines.remove(1))
1221	    }
1222	    let truncated = line.length() > 1024
1223	    let bounded = if truncated {
1224	      incomplete = true
1225	      line[:1024].to_owned()
1226	    } else {
1227	      line.to_owned()
1228	    }
1229	    let bounded = if truncated ||
1230	      (incomplete_final_line && index == source_lines.length() - 1) {
1231	      diagnostic_partial_secret(bounded, progress.secrets)
1232	    } else {
1233	      bounded
1234	    }
1235	    match progress.safe_message(bounded) {
1236	      Some(safe) => lines.push(safe)
1237	      None => {
1238	        incomplete = true
1239	        lines.push("[unavailable]")
1240	      }
1241	    }
1242	  }
1243	  if (incomplete || progress.details_truncated) &&
1244	    lines.last() != Some("[error details incomplete or truncated]") {
1245	    lines.push("[error details incomplete or truncated]")
1246	  }
1247	  lines.join("\n")
1248	}
