1303	///|
1304	fn diagnostic_add_protected(
1305	  value : String,
1306	  output : String,
1307	  uncertain : Bool,
1308	  destination : Array[String],
1309	  result : DiagnosticProtectedValues,
1310	) -> Unit {
1311	  if value == "" ||
1312	    (
1313	      redact_known_values(output, [value]) == output &&
1314	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1315	    ) {
1316	    return
1317	  }
1318	  if result.secrets.length() >= 512 {
