123	///|
124	fn sensitive_name(name : String) -> Bool {
125	  let normalized = name.to_lower().replace_all(old="-", new="_")
126	  if normalized == "ssh_auth_sock" {
127	    return false
128	  }
129	  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
130	    .iter()
131	    .any(suffix => normalized.has_suffix(suffix)) {
132	    return false
133	  }
134	  let credential = credential_field(name, for_diagnostics=true)
135	  let name = name.to_lower()
136	  credential ||
137	  [
138	    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
139	    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
140	  ]
141	  .iter()
142	  .any(marker => name.contains(marker))
143	}
