552	///|
553	fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
554	  if !text.contains("\u001b") {
555	    return text
556	  }
557	  let parts : Array[String] = []
558	  for line in text.split("\n") {
559	    match terminal_text(line.to_owned()) {
560	      Some(safe) => parts.push(safe)
561	      None => {
562	        truncated.val = true
563	        return "[unavailable]"
564	      }
565	    }
566	  }
567	  parts.join("\n")
568	}
