570	///|
571	fn progress_normalize_json(
572	  value : Json,
573	  truncated : Ref[Bool],
574	  depth : Int32,
575	) -> Json {
576	  if depth >= 64 {
577	    truncated.val = true
578	    return Json::string("[unavailable]")
579	  }
580	  match value {
581	    Json::String(text) => Json::string(progress_json_text(text, truncated))
582	    Json::Array(values) =>
583	      Json::array(
584	        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
585	      )
586	    Json::Object(values) => {
587	      let result = Json::empty_object()
588	      for name, item in values {
589	        let key = progress_json_text(name, truncated)
590	        if field(result, key) is Some(_) {
591	          truncated.val = true
592	        } else {
593	          set_field(
594	            result,
595	            key,
596	            progress_normalize_json(item, truncated, depth + 1),
597	          )
598	        }
599	      }
600	      result
601	    }
602	    _ => value
603	  }
604	}
