606	///|
607	fn Progress::filter_output_line(
608	  self : Progress,
609	  line : String,
610	  private_key : Ref[Bool],
611	) -> String? {
612	  let event = @json.parse(line) catch { _ => Json::null() }
613	  self.learn_event(event, line)
614	  let normalized = if event != Json::null() {
615	    let truncated : Ref[Bool] = { val: false, }
616	    let value = progress_normalize_json(event, truncated, 0)
617	    if truncated.val {
618	      self.details_truncated = true
619	      let scanner = PrivateKeyScanner::new(private_key.val)
620	      scanner.feed(line)
621	      private_key.val = scanner.finish()
622	      return None
623	    }
624	    value.stringify()
625	  } else {
626	    match terminal_text(line) {
627	      Some(text) => decode_diagnostic_escapes(text)
628	      None => {
629	        self.details_truncated = true
630	        let scanner = PrivateKeyScanner::new(private_key.val)
631	        scanner.feed(line)
632	        private_key.val = scanner.finish()
633	        return None
634	      }
635	    }
636	  }
637	  let scanner = PrivateKeyScanner::new(private_key.val)
638	  scanner.feed(normalized)
639	  let scanned_private = scanner.finish()
640	  let truncated : Ref[Bool] = { val: false, }
641	  let safe = mask_private_key(normalized, private_key, truncated)
642	  if truncated.val {
643	    self.details_truncated = true
644	  }
645	  if scanned_private && !private_key.val {
646	    self.details_truncated = true
647	    private_key.val = true
648	    guard safe is Some(safe) else { return None }
649	    let chars = safe.iter().to_array()
650	    let prefix = "-----begin ".iter().to_array()
651	    for index in 0..<chars.length() {
652	      if ascii_match_at(chars, index, prefix) {
653	        return Some(character_text(chars, 0, index) + "[private key redacted]")
654	      }
655	    }
656	    return None
657	  }
658	  safe
659	}
