661	///|
662	async fn Progress::line(
663	  self : Progress,
664	  line : String,
665	  statuses~ : Bool,
666	  messages~ : Bool,
667	) -> Unit {
668	  if line.trim() == "" {
669	    return
670	  }
671	  let event = @json.parse(line) catch { _ => Json::null() }
672	  if field(event, "kind") == Some(Json::string("status")) {
673	    if field(event, "state") == Some(Json::string("failed")) &&
674	      field(event, "error") is Some(error) {
675	      for name in ["message", "hint"] {
676	        if field(error, name) is Some(Json::String(text)) {
677	          self.message(
678	            text,
679	            debug=false,
680	            warning=true,
681	            emit=messages || statuses,
682	          )
683	        }
684	      }
685	      self.remember_unrecognized_json(event)
686	    }
687	    if statuses || messages {
688	      self.status(event)
689	    }
690	    return
691	  }
692	  // Result envelopes and arbitrary structured responses are never log text.
693	  if field(event, "kind") == Some(Json::string("result")) {
694	    if field(event, "outcome") == Some(Json::string("success")) &&
695	      field(event, "warnings") is Some(Json::Array(warnings)) {
696	      for warning in warnings {
697	        match warning {
698	          Json::String(text) =>
699	            self.message(
700	              text,
701	              debug=false,
702	              warning=true,
703	              emit=messages || statuses,
704	            )
705	          _ => {
706	            let truncated : Ref[Bool] = { val: false, }
707	            let safe = diagnostic_json(warning, {}, self.secrets, truncated, 0).stringify()
708	            if truncated.val {
709	              self.details_truncated = true
710	            }
711	            self.message(safe, debug=false, warning=true, emit=false)
712	          }
713	        }
714	      }
715	    }
716	    if field(event, "outcome") != Some(Json::string("success")) &&
717	      (
718	        field(event, "error") is Some(_) ||
719	        field(event, "message") is Some(_) ||
720	        field(event, "code") is Some(_) ||
721	        field(event, "outcome") == Some(Json::string("failure")) ||
722	        field(event, "outcome") == Some(Json::string("error"))
723	      ) {
724	      self.remember_unrecognized_json(event)
725	    }
726	    return
727	  }
728	  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
729	    return
730	  }
731	  if event is Json::Object(_) {
732	    let kind = field(event, "kind")
733	    guard kind == None ||
734	      kind == Some(Json::string("log")) ||
735	      kind == Some(Json::string("error")) else {
736	      self.remember_unrecognized_json(event)
737	      return
738	    }
739	    let message = match field(event, "msg") {
740	      Some(value) => Some(value)
741	      None =>
742	        match field(event, "message") {
743	          Some(value) => Some(value)
744	          None =>
745	            match field(event, "error") {
746	              Some(Json::Object(_) as value) => field(value, "message")
747	              value => value
748	            }
749	        }
750	    }
751	    guard message is Some(Json::String(text)) else {
752	      self.remember_unrecognized_json(event)
753	      return
754	    }
755	    let level = field(event, "level")
756	    self.message(
757	      text,
758	      debug=level == Some(Json::string("debug")) ||
759	        level == Some(Json::string("trace")),
760	      warning=kind == Some(Json::string("error")) ||
761	        level == Some(Json::string("warn")) ||
762	        level == Some(Json::string("error")),
763	      emit=messages || (statuses && kind != None),
764	    )
765	  } else {
766	    if event != Json::null() {
767	      self.remember_unrecognized_json(event)
768	      return
769	    }
770	    // Malformed JSON and binary output are not a safe free-text fallback.
771	    let text = line.trim().to_owned()
772	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
773	      self.message(text, debug=false, warning=true, emit=messages)
774	      return
775	    }
776	    if text.has_prefix("{") || text.has_prefix("[") {
777	      self.details_truncated = true
778	      self.remember_unrecognized(text)
779	      return
780	    }
781	    self.message(
782	      text,
783	      debug=text.contains(" DEBUG ") ||
784	        text.contains(" TRACE ") ||
785	        text.has_prefix("DEBUG ") ||
786	        text.has_prefix("TRACE "),
787	      warning=text.contains(" WARN ") ||
788	        text.contains(" ERROR ") ||
789	        text.has_prefix("WARN ") ||
790	        text.has_prefix("ERROR "),
791	      emit=messages,
792	    )
793	  }
794	}
