796	///|
797	async fn Progress::stderr_line(
798	  self : Progress,
799	  line : String,
800	  statuses~ : Bool,
801	  messages~ : Bool,
802	) -> Unit {
803	  let event = @json.parse(line) catch { _ => Json::null() }
804	  if event != Json::null() {
805	    self.line(line, statuses~, messages~)
806	    let truncated : Ref[Bool] = { val: false, }
807	    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
808	    if truncated.val {
809	      self.details_truncated = true
810	    }
811	    if field(event, "kind") == Some(Json::string("error")) ||
812	      [Some(Json::string("warn")), Some(Json::string("error"))].contains(
813	        field(event, "level"),
814	      ) ||
815	      field(event, "state") == Some(Json::string("failed")) {
816	      self.message(safe, debug=false, warning=true, emit=false)
817	    } else {
818	      self.remember_unrecognized(safe)
819	    }
820	    return
821	  } else if event == Json::null() &&
822	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
823	    self.details_truncated = true
824	    self.message(line, debug=false, warning=true, emit=false)
825	    return
826	  }
827	  self.line(line, statuses~, messages~)
828	}
