830	///|
831	async fn Progress::read_output(
832	  self : Progress,
833	  reader : @process.ReadFromProcess,
834	  capture~ : Bool,
835	  statuses~ : Bool = false,
836	  messages~ : Bool = false,
837	  raw_messages~ : Bool = false,
838	) -> String {
839	  let output = @buffer.Buffer(size_hint=4096)
840	  let pending = @buffer.Buffer(size_hint=4096)
841	  let private_key : Ref[Bool] = { val: false, }
842	  let mut scanner : PrivateKeyScanner? = None
843	  let mut oversized = false
844	  let mut tail = ""
845	  while reader.read_some(max_len=4096) is Some(chunk) {
846	    if capture {
847	      output.write_bytes(chunk)
848	    } else {
849	      tail += @utf8.decode_lossy(chunk)
850	      if tail.length() > 8192 {
851	        tail = tail[tail.length() - 8192:].to_owned()
852	      }
853	    }
854	    for byte in chunk {
855	      if byte == b'\n' || byte == b'\r' {
856	        if oversized && scanner is Some(current) {
857	          current.feed(@utf8.decode_lossy(pending.to_bytes()))
858	          private_key.val = current.finish()
859	          scanner = None
860	        } else if pending.length() > 0 {
861	          let malformed : Ref[Bool] = { val: false, }
862	          let line = @utf8.decode(pending.to_bytes()) catch {
863	            _ => {
