145	///|
146	fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
147	  if value == "" {
148	    return
149	  }
150	  let values = [value]
151	  for part in value.replace_all(old="\r", new="\n").split("\n") {
152	    if part.trim() != "" && part.length() < value.length() {
153	      values.push(part.to_owned())
154	    }
155	  }
156	  for item in values {
157	    if !secrets.contains(item) {
158	      secrets.push(item)
159	    }
160	    let encoded = Json::string(item).stringify()
161	    let escaped = encoded[1:encoded.length() - 1].to_owned()
162	    if escaped != item && !secrets.contains(escaped) {
163	      secrets.push(escaped)
164	    }
165	  }
166	}
