216	///|
217	fn terminal_text(text : String) -> String? {
218	  let output = @buffer.Buffer(size_hint=256)
219	  let mut state = 0
220	  for c in text.iter() {
221	    match state {
222	      0 =>
223	        if c == '\u001b' {
224	          state = 1
225	        } else if c.to_int() < 32 && c != '\t' {
226	          return None
227	        } else {
228	          output.write_char_utf8(c)
229	        }
230	      1 =>
231	        if c == '[' {
232	          state = 2
233	        } else if c == ']' {
234	          state = 3
235	        } else {
236	          return None
237	        }
238	      2 => if c >= '@' && c <= '~' { state = 0 }
239	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
240	      _ => if c == '\\' { state = 0 } else { state = 3 }
241	    }
242	  }
243	  if state != 0 {
244	    None
245	  } else {
246	    Some(@utf8.decode_lossy(output.to_bytes()))
247	  }
248	}
