  34	///|
  35	async fn command_result(
  36	  program : String,
  37	  args : Array[String],
  38	  stage : String,
  39	  environment? : Map[String, String],
  40	  cwd? : StringView,
  41	  target? : String,
  42	  recording_override? : Bool,
  43	  protected_secrets? : Array[String],
  44	  protection_incomplete~ : Bool = false,
  45	  invocation_evidence? : Json,
  46	) -> (Int32, String, String) {
  47	  let protection_incomplete = protection_incomplete ||
  48	    create_recording.protection_incomplete
  49	  let recording = recording_override.unwrap_or(
  50	    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
  51	    Some("0"),
  52	  )
  53	  let context : Json? = if recording {
  54	    diagnostic_operation_counter.val += 1
  55	    let value : Json = {
  56	      "operationId": recording_run_id +
  57	      ":" +
  58	      diagnostic_operation_counter.val.to_string(),
  59	    }
  60	    if target is Some(id) {
  61	      set_field(value, "workspaceId", Json::string(id))
  62	    }
  63	    if invocation_evidence is Some(invocation) {
  64	      set_field(value, "invocation", invocation)
  65	    }
  66	    Some(value)
  67	  } else {
  68	    None
  69	  }
  70	  save_diagnostic(
  71	    stage,
  72	    "started",
  73	    evidence?=context,
  74	    evidence_stable_operation=true,
  75	    environment?,
  76	    protected_secrets?,
  77	    recording~,
  78	  )
  79	  let started = @env.now()
  80	  let progress = Progress::new(
  81	    stage,
  82	    environment?,
  83	    context?,
  84	    recording_override=recording,
  85	    protected_secrets?,
  86	    protection_incomplete~,
  87	  )
  88	  let label = target
  89	    .map(value => {
  90	      diagnostic_text(value, protected_secrets=progress.secrets) + ": " + stage
  91	    })
  92	    .unwrap_or(stage)
  93	  progress_message(label + ": running…")
  94	  let mut failure_kind = "process_api"
  95	  let mut failure_errno = None
  96	  let mut failure_phase = None
  97	  let (status, output, errors) = {
  98	    errdefer {
  99	      save_diagnostic(
 100	        stage,
 101	        if @async.is_being_cancelled() {
 102	          "cancelled"
 103	        } else {
 104	          "process-error"
 105	        },
 106	        error_type=failure_kind,
 107	        os_errno?=failure_errno,
 108	        phase?=failure_phase,
 109	        error_message=progress.failure_detail(),
 110	        details_truncated=progress.details_truncated,
 111	        evidence?=context,
 112	        evidence_stable_operation=true,
 113	        environment?,
 114	        protected_secrets?,
 115	        recording~,
 116	      )
 117	      progress_message(label + ": failed (" + progress_timing(started) + ")")
 118	    }
 119	    try {
 120	      let (out, stdout) = @process.read_from_process()
 121	      defer out.close()
 122	      let (err, stderr) = @process.read_from_process()
 123	      defer err.close()
 124	      @async.with_task_group(async fn(group) {
 125	        let child = @process.spawn(
 126	          group,
 127	          program,
 128	          args,
 129	          extra_env?=environment,
 130	          inherit_env=environment is None,
 131	          cwd?,
 132	          stdout~,
 133	          stderr~,
 134	        )
 135	        let output = group.spawn(async fn() {
 136	          progress.read_output(
 137	            out,
 138	            capture=true,
 139	            statuses=devsy_progress_stage(stage),
 140	            messages=stage == "orca-install" || stage == "checkout-workspace",
 141	          )
 142	        })
 143	        let errors = group.spawn(async fn() {
 144	          progress.read_output(
 145	            err,
 146	            capture=false,
 147	            messages=devsy_progress_stage(stage) ||
 148	              stage == "orca-install" ||
 149	              stage == "checkout-workspace",
 150	          )
 151	        })
 152	        (child.wait(), output.wait(), errors.wait())
 153	      })
 154	    } catch {
 155	      @os_error.OSError(code, ..) as error => {
 156	        failure_kind = "process_os"
 157	        failure_errno = Some(code)
 158	        let message = if protection_incomplete {
 159	          progress.details_truncated = true
 160	          "subprocess OS error \{code}; workspace protection values unavailable"
 161	        } else {
 162	          progress
 163	          .safe_message(program + ": " + error.to_string())
 164	          .unwrap_or("subprocess OS error \{code}")
 165	        }
 166	        progress.remember(message, warning=true)
 167	        raise AdapterError(
 168	          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
 169	          message,
 170	        )
 171	      }
 172	      @utf8.Malformed(_) => {
 173	        failure_kind = "process_utf8"
 174	        failure_phase = Some("read")
 175	        progress.remember("subprocess output is not valid UTF-8", warning=true)
 176	        raise AdapterError(
 177	          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
 178	        )
 179	      }
 180	      error => {
 181	        if !@async.is_being_cancelled() {
 182	          let detail = if protection_incomplete {
 183	            progress.details_truncated = true
 184	            "error detail unavailable because workspace protection values could not be read"
 185	          } else {
 186	            diagnostic_text(
 187	              diagnostic_error(error, environment?),
 188	              environment?,
 189	              protected_secrets=progress.secrets,
 190	            )
 191	          }
 192	          for line in detail.split("\n") {
 193	            progress.remember(line.to_owned(), warning=true)
 194	          }
 195	        }
 196	        raise error
 197	      }
 198	    }
 199	  }
 200	  if status != 0 {
 201	    for line in progress.unrecognized {
 202	      progress.remember(line, warning=true)
 203	    }
 204	  }
 205	  let output_secrets = [] + progress.secrets
 206	  let mut output_protection_incomplete = false
 207	  let mut server_signal = false
 208	  if stage == "orca-serve" {
 209	    for line in output.split("\n") {
 210	      let result = @json.parse(line.to_owned()) catch { _ => Json::null() }
 211	      if field(result, "kind") ==
 212	        Some(Json::string("orca-env-devsy-server-exit")) &&
 213	        field(result, "runId") == Some(Json::string(recording_run_id)) &&
 214	        field(result, "number") ==
 215	        Some(Json::number((status - 128).to_double())) &&
 216	        status > 128 &&
 217	        status <= 255 {
 218	        server_signal = true
 219	      }
 220	      let connection = field(result, "connection").unwrap_or(result)
 221	      if field(connection, "pairingCode") is Some(Json::String(pairing)) &&
 222	        pairing != "" {
 223	        if pairing.length() > 65536 {
 224	          output_protection_incomplete = true
 225	        } else {
 226	          add_protected_secret(output_secrets, pairing)
 227	        }
 228	      }
 229	    }
 230	  }
 231	  let mut detail = if output_protection_incomplete {
 232	    progress.details_truncated = true
 233	    "error detail unavailable because server protection values exceed the limit\n[error details incomplete or truncated]"
 234	  } else {
 235	    diagnostic_text(
 236	      progress.failure_detail(),
 237	      environment?,
 238	      protected_secrets=output_secrets,
 239	    )
 240	  }
