1894	async fn snapshot_workspace_recording(state : Json, directory : String) -> Unit {
1895	  let mut reason = "enabled"
1896	  let enabled = if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
1897	    reason = "process_opt_out"
1898	    false
1899	  } else {
1900	    let value = try {
1901	      guard diagnostic_read_file(directory + "/environment.json", 4194304L)
1902	        is Some(raw) else {
1903	        raise AdapterError("Saved recording settings unavailable")
1904	      }
1905	      let environment = @json.parse(raw)
1906	      guard environment is Json::Object(_) else {
1907	        raise AdapterError("Invalid saved recording settings")
1908	      }
1909	      Some(recording_from_environment(environment))
1910	    } catch {
1911	      error => if @async.is_being_cancelled() { raise error } else { None }
1912	    }
1913	    if value is None {
1914	      reason = "workspace_recording_unknown"
1915	      diagnostic_recording_warning(
1916	        "workspace_recording_unknown",
1917	        phase="configuration",
1918	      )
1919	    }
1920	    if value == Some(false) {
1921	      reason = "workspace_opt_out"
1922	    }
1923	    value.unwrap_or(false)
1924	  }
1925	  set_field(state, "diagnosticRecording", Json::boolean(enabled))
1926	  set_field(state, "diagnosticRecordingReason", Json::string(reason))
