1929	///|
1930	async fn saved_workspace_secrets(
1931	  state : Json,
1932	  for_output~ : Bool = false,
1933	  include_pairing~ : Bool = true,
1934	) -> Array[String]? {
1935	  if !for_output && !state_recording(state) {
1936	    return Some([])
1937	  }
1938	  try {
1939	    let directory = required(state, "tunnelDirectory")
1940	    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
1941	      is Some(raw) else {
1942	      return None
1943	    }
1944	    let saved = @json.parse(raw)
1945	    guard saved is Json::Object(values) else { return None }
1946	    let environment : Map[String, String] = Map([])
1947	    for name, value in values {
1948	      guard value is Json::String(value) else { return None }
1949	      environment.set(name, value)
1950	    }
1951	    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
1952	    let invocation = saved_command(state)
1953	    let sources = invocation.mapi((index, _) => "command[\{index}]")
1954	    let (_, invocation_secrets, invocation_incomplete) = up_arguments_evidence(
1955	      invocation, sources,
1956	    )
1957	    guard !invocation_incomplete else { return None }
1958	    for value in invocation_secrets {
1959	      add_protected_secret(secrets, value)
1960	    }
1961	    if include_pairing {
1962	      guard workspace_pairing_secrets(state) is Some(pairing) else {
1963	        return None
1964	      }
1965	      for value in pairing {
1966	        secrets.push(value)
1967	      }
1968	    }
1969	    Some(secrets)
1970	  } catch {
1971	    error => if @async.is_being_cancelled() { raise error } else { None }
1972	  }
1973	}
