1538	///|
1539	async fn DiagnosticCapture::read(
1540	  self : DiagnosticCapture,
1541	  reader : @process.ReadFromProcess,
1542	) -> Unit {
1543	  try {
1544	    while reader.read_some(max_len=4096) is Some(chunk) {
1545	      let remaining = self.limit - self.output.length()
1546	      let count = if chunk.length() < remaining {
1547	        chunk.length()
1548	      } else {
1549	        remaining
1550	      }
1551	      if count > 0 {
1552	        self.output.write_bytes(chunk[:count])
1553	      }
1554	      if count < chunk.length() {
1555	        self.truncated = true
1556	      }
1557	    }
1558	  } catch {
1559	    error =>
1560	      if @async.is_being_cancelled() {
1561	        raise error
1562	      } else {
1563	        self.truncated = true
1564	      }
1565	  }
1566	  self.finished = true
1567	}
