1580	///|
1581	async fn diagnostic_process_output(
1582	  program : String,
1583	  args : Array[String],
1584	  environment~ : Map[String, String],
1585	  cwd? : StringView,
1586	  stdin? : &@process.ProcessInput,
1587	  stdout_limit~ : Int32,
1588	  stderr_limit~ : Int32,
1589	  stderr_capture? : DiagnosticCapture,
1590	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1591	  let (out, stdout) = @process.read_from_process()
1592	  defer out.close()
1593	  let (err, stderr) = @process.read_from_process()
1594	  defer err.close()
1595	  @async.with_task_group(async fn(group) {
1596	    let child = @process.spawn(
1597	      group,
1598	      program,
1599	      args,
1600	      extra_env=environment,
1601	      inherit_env=false,
1602	      cwd?,
1603	      stdin?,
1604	      stdout~,
1605	      stderr~,
1606	    )
1607	    let output = DiagnosticCapture::new(stdout_limit)
1608	    let errors = stderr_capture.unwrap_or(DiagnosticCapture::new(stderr_limit))
1609	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1610	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1611	    let status = child.wait()
1612	    if status == 0 {
1613	      while !output.finished {
1614	        @async.sleep(5)
1615	      }
1616	      wait_diagnostic_captures([errors])
1617	    } else {
1618	      wait_diagnostic_captures([output, errors])
1619	    }
1620	    (
1621	      status,
1622	      output.output.to_bytes(),
1623	      output.truncated || !output.finished,
1624	      errors.output.to_bytes(),
1625	      errors.truncated || !errors.finished,
1626	    )
1627	  })
1628	}
