443	pub async fn recover_all(restart~ : Bool = false) -> Unit {
444	  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
445	  let mut failure_recorded = false
446	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
447	    @async.protect_from_cancel(async fn() {
448	      save_diagnostic("recover", "cancelled", error_type="cancelled")
449	    })
450	  })
451	  recover_all_inner(restart~) catch {
452	    AdapterError(message) => {
453	      let detail = diagnostic_error(AdapterError(message))
454	      progress_write("orca-env-devsy: " + detail + "\n")
455	      save_command_failure("recover", AdapterError(message))
456	      failure_recorded = true
457	      raise AdapterError(message)
458	    }
459	    error => {
460	      progress_write(
461	        "orca-env-devsy: bulk recover failed; inspect local diagnostics\n",
462	      )
463	      save_command_failure("recover", error)
464	      failure_recorded = true
465	      raise AdapterError("Bulk recover failed")
466	    }
467	  }
468	}
