470	///|
471	async fn recover_all_inner(restart~ : Bool = false) -> Unit {
472	  notify(if restart { "restart" } else { "recover" })
473	  @fs.mkdir(
474	    adapter_state_home(),
475	    recursive=true,
476	    permission=0o700,
477	    allow_exist=true,
478	  )
479	  let bulk_lock = @fs.open(
480	    adapter_state_home() + "/bulk-recovery.lock",
481	    mode=ReadWrite,
482	    create_mode=OpenOrCreate,
483	    permission=0o600,
484	  )
485	  defer bulk_lock.close()
486	  @async.with_timeout(60000, async fn() {
487	    while !bulk_lock.try_lock(Exclusive) {
488	      @async.sleep(25)
489	    }
490	  })
491	  let base = adapter_state_home() + "/tunnels"
492	  if !restart &&
493	    !@fs.exists(base) &&
494	    !@fs.exists(adapter_state_home() + "/transports") {
495	    save_diagnostic("recover", "success")
496	    return
497	  }
498	  ignore(saved_proxy_executable())
499	  let transport_failures = if restart {
500	    restart_supervisor()
501	  } else {
502	    ensure_supervisor()
503	    0
504	  }
505	  if !@fs.exists(base) {
506	    guard transport_failures == 0 else {
507	      raise AdapterError("Some SSH transports could not be cleaned up")
508	    }
509	    save_diagnostic("recover", "success")
510	    return
511	  }
512	  let mut failures = transport_failures
513	  let permits = @async.Semaphore(4)
514	  @async.with_task_group(async fn(group) {
515	    for name in @fs.readdir(base, sort=true) {
516	      let directory = base + "/" + name
517	      permits.acquire()
518	      group.spawn_bg(async fn() {
519	        defer permits.release()
520	        let mut target = "[unavailable]"
521	        let tracking : Json = {
522	          "diagnosticRecording": false,
523	          "tunnelDirectory": directory,
524	        }
525	        let mut target_state : Json? = Some(tracking)
526	        try {
527	          if @fs.kind(directory, follow_symlink=false) !=
528	            @fs.FileKind::Directory ||
529	            !@fs.exists(directory + "/enabled") {
530	            return
531	          }
532	          snapshot_workspace_recording(tracking, directory)
533	          let state = @json.parse(
534	            @fs.read_file(directory + "/state.json").text(),
535	          )
536	          set_field(
537	            state,
538	            "diagnosticRecording",
539	            field(tracking, "diagnosticRecording").unwrap(),
540	          )
541	          validate_state(state)
542	          set_field(state, "tunnelDirectory", Json::string(directory))
543	          target = workspace_text(state, required(state, "workspaceId"))
544	          progress_message(
545	            target +
546	            ": " +
547	            (if restart { "restart" } else { "recover" }) +
548	            " running…",
549	          )
550	          target_state = Some(state)
551	          recover_connection(state, restart~, saved_environment=true)
552	          progress_message(
553	            target +
554	            ": " +
555	            (if restart { "restart" } else { "recover" }) +
556	            " done",
557	          )
558	        } catch {
559	          error =>
560	            if @fs.exists(directory) {
561	              failures += 1
562	              let environment = target_state.map(state => {
563	                workspace_environment(state)
564	              })
565	              let message = diagnostic_error(error, environment?)
566	              let ssh_detail = if message.contains(
567	                  "SSH and relay readiness timed out",
568	                ) &&
569	                !message.contains("last connection failure:") {
570	                connection_failure(directory, [
571	                  "worker-error.json", "ssh-error.json",
572	                ]).unwrap_or("SSH failure details unavailable")
573	              } else {
574	                ""
575	              }
576	              let combined = message +
577	                (if ssh_detail == "" {
578	                  ""
579	                } else {
580	                  "\nlast connection failure: " + ssh_detail
581	                })
582	              let detail = if target_state is Some(state) {
583	                workspace_error_detail(state, AdapterError(combined))
584	              } else {
585	                diagnostic_text(combined, environment?)
586	              }
587	              if target == "[unavailable]" && target_state is Some(state) {
588	                target = workspace_text(state, name)
589	              }
590	              progress_message(target + ": failed: " + detail)
591	              save_diagnostic(
592	                "recover",
593	                "failed",
594	                tunnel_directory=directory,
595	                error_type="target_failed",
596	                error_message=detail,
597	                recording?=target_state.map(state => operation_recording(state)),
598	              )
599	            } else {
600	              save_diagnostic("recover", "target-removed")
601	            }
602	        }
603	      })
604	    }
605	  })
606	  guard failures == 0 else {
607	    raise AdapterError(
608	      "Some connections could not be recovered; other targets were attempted",
609	    )
610	  }
611	  save_diagnostic("recover", "success")
612	}
